parameters.jsCode:
// Turn Claude's JSON into flat workflow fields.
//
// The model is told to return bare JSON. We never trust that blindly: fences,
// stray prose, or an invented track must not break the run or - worse -
// quietly become a real onboarding decision.

const TRACKS = [
  'standard',
  'tipped_employees',
  'multi_state_remote',
  'contractor_heavy',
  'needs_review',
];

function extractJson(text) {
  if (!text) return null;
  let t = String(text).trim();
  t = t.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  const start = t.indexOf('{');
  const end = t.lastIndexOf('}');
  if (start === -1 || end === -1 || end <= start) return null;
  try {
    return JSON.parse(t.slice(start, end + 1));
  } catch (err) {
    return null;
  }
}

function truthy(v) {
  if (typeof v === 'boolean') return v;
  return ['true', 'yes', '1'].includes(String(v ?? '').trim().toLowerCase());
}

const signups = $('Normalize Signup').all();
const incoming = $input.all();
const results = [];

for (let i = 0; i < incoming.length; i++) {
  const signup = signups[Math.min(i, signups.length - 1)].json;
  const parsed = extractJson(incoming[i].json.merged_response);

  // Fail safe. An unclassified signup goes to a person, never to a guessed
  // track - not guessing is the entire point of this workflow.
  if (!parsed) {
    results.push({
      json: {
        ...signup,
        onboarding_track: 'needs_review',
        flag_for_human: true,
        flag_reason: 'Automatic classification failed - model output was not valid JSON.',
        internal_summary: 'Signup received but could not be classified automatically.',
        welcome_email_draft: '(no draft - classification failed, write one by hand)',
        status: 'needs_review',
      },
      pairedItem: { item: i },
    });
    continue;
  }

  const raw = String(parsed.onboarding_track ?? '').trim().toLowerCase();
  const known = TRACKS.includes(raw);
  const track = known ? raw : 'needs_review';

  let flag = truthy(parsed.flag_for_human);
  let reason = String(parsed.flag_reason ?? '').trim();

  // A track outside the allowed set is itself a reason to involve a person.
  if (!known) {
    flag = true;
    reason = reason || ('Model returned an unrecognised track: "' + raw + '".');
  }

  // needs_review and flag_for_human have to agree. Picking needs_review is
  // the model saying it cannot decide - that is a flag, whatever it wrote in
  // the boolean.
  if (track === 'needs_review') {
    flag = true;
    reason = reason || 'Classified as needs_review without a stated reason.';
  }

  // A flag with no reason is useless to whoever picks this up.
  if (flag && !reason) reason = 'Flagged by the model without a stated reason.';
  if (!flag) reason = '';

  results.push({
    json: {
      ...signup,
      onboarding_track: track,
      flag_for_human: flag,
      flag_reason: reason,
      internal_summary:
        String(parsed.internal_summary ?? '').trim() || 'No summary returned.',
      welcome_email_draft:
        String(parsed.welcome_email_draft ?? '').trim() ||
        '(no draft returned - write one by hand)',
      status: flag ? 'needs_review' : 'auto_drafted',
    },
    pairedItem: { item: i },
  });
}

return results;

// One signup becomes one row per starter task.
//
// This is a lookup, not a judgement, so it is deliberately not a second model
// call. The track has already been decided; which starter tasks belong to a
// known track is fixed knowledge, and it belongs in code where it can be read
// and changed without re-testing a prompt.
//
// needs_review has its own list on purpose. Without one, the flagged signup -
// the row that most needs someone to act - would be the only one that
// produced no tasks at all.

const CHECKLISTS = {
  standard: [
    'Confirm pay schedule and first pay date',
    'Collect employee records and W-4s',
    'Verify state tax registration for their filing state',
    'Book 20-minute setup call',
  ],
  tipped_employees: [
    'Confirm tip-pooling method and who takes part',
    'Set up tipped minimum wage and tip credit for their state',
    'Configure declared-tip reporting on each pay run',
    'Book 20-minute setup call',
  ],
  multi_state_remote: [
    'List every state an employee actually works in',
    'Register for withholding in each new state',
    'Set reciprocity and local tax rules per employee',
    'Book 30-minute multi-state setup call',
  ],
  contractor_heavy: [
    'Separate 1099 contractors from W-2 employees in the roster',
    'Collect W-9s and confirm payment method for each contractor',
    'Enable 1099-NEC year-end filing',
    'Book 20-minute setup call',
  ],
  needs_review: [
    'Do not begin setup - this signup needs a human look first',
    'Read the flag reason and decide which track applies',
    'Reply to the customer once the track is confirmed',
  ],
};

const incoming = $input.all();
const rows = [];

for (let i = 0; i < incoming.length; i++) {
  const s = incoming[i].json;
  const tasks = CHECKLISTS[s.onboarding_track] || CHECKLISTS.needs_review;

  for (const task of tasks) {
    rows.push({
      json: {
        // Same timestamp and id as the customers row. The id is what the ops
        // console joins on - company name would collide the moment the same
        // demo signup is submitted twice.
        timestamp: s.timestamp,
        signup_id: s.signup_id,
        company_name: s.company_name,
        task: task,
        done: 'no',
      },
      pairedItem: { item: i },
    });
  }
}

return rows;

